from pathlib import Path
import hashlib
p=Path.cwd()
for d in [*reversed(p.parents),p]:
 f=d/'AGENTS.md'
 if f.exists(): print('INSTRUCTIONS',f,'\\n',f.read_text())
for name in ['problem.md','prd.md','chain-notes.md','authored.sha256.json','.eval-plugins/product/skills/prd-gate/SKILL.md','.eval-plugins/product/references/artifact-contract.md','.eval-plugins/product/references/prd-review-contract.md']:
 b=Path(name).read_bytes()
 print(name,hashlib.sha256(b).hexdigest())
 if name in ['problem.md','prd.md','chain-notes.md']:
  for i,line in enumerate(b.decode().splitlines(),1): print(f'{i}: {line}')
print('Existing reports:',[f for f in ['report.md','report.json'] if Path(f).exists()])
PY"

